package lzfse

// Code generated at development time from streams produced by the pure-Rust
// lzfse_rust reference encoder (and, for the v1 vector, by rewriting the same
// block's v2 weight tables into the v1 layout). Every vector was decoded with
// that reference decoder before being embedded. The tests are hermetic: no
// external tool is run at test time.

type testVector struct {
	name   string
	stream []byte
	want   []byte
}

var testVectors = []testVector{
	{name: "hello", stream: mustHex("6276782d0e00000068656c6c6f2c206c7a667365210a62767824"), want: mustHex("68656c6c6f2c206c7a667365210a")},
	{name: "quick", stream: mustHex("6276786e4605000043000000e01d54686520717569636b2062726f776e20666f78206a756d7073206f76657220746865206c617a7920646f672e20382df0fff0fff0fff0fff0c3060000000000000062767824"), want: mustHex("")},
	{name: "aaaa", stream: mustHex("6276786e001000002b000000680141f0fff0fff0fff0fff0fff0fff0fff0fff0fff0fff0fff0fff0fff0fff0fff006060000000000000062767824"), want: mustHex("")},
	{name: "noise512", stream: mustHex(""), want: mustHex("")},
	{name: "mixed", stream: mustHex(""), want: genMixed()},
	{name: "raw-then-vn", stream: mustHex("6276782d0e00000068656c6c6f2c206c7a667365210a6276786e4605000043000000e01d54686520717569636b2062726f776e20666f78206a756d7073206f76657220746865206c617a7920646f672e20382df0fff0fff0fff0fff0c3060000000000000062767824"), want: mustHex("")},
	{name: "vn-then-raw", stream: mustHex(""), want: mustHex("")},
	{name: "v2-v2", stream: mustHex(""), want: concat(genMixed(), genMixed2())},
	{name: "v2-vn-raw", stream: mustHex(""), want: concat(genMixed(), genQuick())},
	{name: "v1", stream: mustHex(""), want: genMixed()},
	{name: "lzvn", stream: mustHex("6276786e060000000c00000088026162060000000000000062767824"), want: mustHex("616261626162")},
}
